from scipy.optimize import least_squares
forms={
 'A: c*T^p + d*eps^q': lambda p: p[0]*T**3/(1+p[1]*eps)+p[2]*T**p[3]+p[4]*eps**p[5]-sigma,
 'B: c*T^p + d*eps*T^q': lambda p: p[0]*T**3/(1+p[1]*eps)+p[2]*T**p[3]+p[4]*eps*T**p[5]-sigma,
 'C: c*T^p*eps^q + d*eps': lambda p: p[0]*T**3/(1+p[1]*eps)+p[2]*T**p[3]*eps**p[5]+p[4]*eps-sigma,
}
np.random.seed(1)
for name,fn in forms.items():
    best=None
    for s in range(40):
        x0=np.r_[0.05+0.05*np.random.rand(), 0.2+2*np.random.rand(), np.random.randn()*3, 0.5+np.random.rand(), np.random.randn(), 0.5+np.random.rand()]
        try:
            r=least_squares(fn,x0)
        except Exception: continue
        if np.all(np.isfinite(r.fun)) and (best is None or r.cost<best.cost): best=r
    print(name, best.cost, np.round(best.x,5))
